using System;using System.Collections;using System.IO;using System.Text;using UnityEngine;using LighFight.Runtime;using LighFight.Core;using LazySourceContact;
namespace SourceContactReview {
 // Runnable REVIEW entrypoint. Assign approved Sailor prefab with prepared adapter fixtures.
 // Uses fresh actors per scenario; never modifies original assets or the production catalog.
 public sealed class SourceNearRangeAudit:MonoBehaviour {
  public GameObject preparedActorPrefab;public TextAsset originalMeshFixture,compactFixture,allInfluencesFixture,originalBoneNames;public string outputDirectory="/tmp/LighFightSourceNearRangeAudit";public bool quitWhenFinished;public float timeoutSeconds=120;public bool Completed{get;private set;}public bool Passed{get;private set;}public string Failure{get;private set;}
  readonly StringBuilder report=new StringBuilder();GameObject actorA,actorB;float deadline;IEnumerator scenario,activeCase;
  IEnumerator Start(){deadline=Time.realtimeSinceStartup+timeoutSeconds;scenario=Run();while(true){bool next=false;object current=null;try{if(Time.realtimeSinceStartup>deadline)throw new TimeoutException("Bounded source audit deadline");next=scenario.MoveNext();if(next)current=scenario.Current;}catch(Exception error){Failure=error.ToString();break;}if(!next)break;yield return current;}try{(scenario as IDisposable)?.Dispose();}finally{ReleaseActors();Completed=true;Passed=false;report.AppendLine("gameplayAccepted=false; temporalCertificateMissing=true; failure="+Failure);try{Directory.CreateDirectory(outputDirectory);File.WriteAllText(Path.Combine(outputDirectory,"audit.txt"),report.ToString());}catch(Exception error){Failure=(Failure??"")+" report: "+error;Debug.LogException(error);}finally{if(quitWhenFinished)Application.Quit();}}}
  void ReleaseActors(){foreach(var actor in new[]{actorA,actorB})if(actor){foreach(var component in actor.GetComponentsInChildren<MonoBehaviour>(true)){var owner=component as IActorCurveWarmup;if(owner!=null){owner.CancelWarmup();owner.Dispose();}}Destroy(actor);}actorA=actorB=null;}
  void OnDestroy(){(activeCase as IDisposable)?.Dispose();(scenario as IDisposable)?.Dispose();ReleaseActors();}
  IEnumerator Run(){Directory.CreateDirectory(outputDirectory);if(!preparedActorPrefab)throw new InvalidOperationException("Assign approved prepared source prefab");try{foreach(float gap in new[]{.65f,.9f,3f})foreach(int move in new[]{0,1}){yield return null;activeCase=Case(gap,0,move);while(activeCase.MoveNext())yield return activeCase.Current;(activeCase as IDisposable)?.Dispose();activeCase=null;}foreach(int move in new[]{0,1}){activeCase=Case(.9f,1.3f,move);while(activeCase.MoveNext())yield return activeCase.Current;(activeCase as IDisposable)?.Dispose();activeCase=null;}}finally{(activeCase as IDisposable)?.Dispose();activeCase=null;ReleaseActors();}}
  SourceSurfaceReviewAdapter Configure(GameObject actor){var adapter=actor.GetComponent<SourceSurfaceReviewAdapter>();if(adapter)return adapter;adapter=actor.AddComponent<SourceSurfaceReviewAdapter>();foreach(var skin in actor.GetComponentsInChildren<SkinnedMeshRenderer>(true))if(skin.sharedMesh&&skin.sharedMesh.vertexCount==57025){if(adapter.sourceSkin)throw new InvalidOperationException("Ambiguous original source renderer");adapter.sourceSkin=skin;}adapter.originalMeshFixture=originalMeshFixture;adapter.compactFixture=compactFixture;adapter.allInfluencesFixture=allInfluencesFixture;adapter.originalBoneNames=originalBoneNames;return adapter;}
  IEnumerator Case(float gap,float side,int moveIndex){actorA=Instantiate(preparedActorPrefab);actorB=Instantiate(preparedActorPrefab);var va=actorA.GetComponent<FighterView>();var vb=actorB.GetComponent<FighterView>();var a=Configure(actorA);var b=Configure(actorB);if(!va||!vb||!a||!b)throw new InvalidOperationException("Actual FighterView + source adapter required on prefab root");va.FullPreviewMotion=vb.FullPreviewMotion=false;
   // Warm ALL actual typed owners including native curves before any sampling.
   foreach(var actor in new[]{actorA,actorB})foreach(var component in actor.GetComponentsInChildren<MonoBehaviour>(true)){var owner=component as IActorCurveWarmup;if(owner==null)continue;var warm=owner.Warmup();try{while(warm.MoveNext()){if(Time.realtimeSinceStartup>deadline)throw new TimeoutException("Actor warmup");yield return warm.Current;}}finally{(warm as IDisposable)?.Dispose();}}
   var fa=new Fighter{X=-gap*.5f};var fb=new Fighter{X=gap*.5f,FacingX=-1};va.SampleContactPose(fa,fb);vb.SampleContactPose(fb,fa);var inspection=new CandidatePairInspection();string label=Moves.All[moveIndex].Id+"-"+gap+"-side"+side;bool startBad=false;int contacts=0,unknown=0;
   for(int frame=-1;frame<=Moves.All[moveIndex].Duration;frame++){if(frame==0)fa.Start(moveIndex);if(frame>=0)fa.Frame=frame;if(frame==8)fb.Z=side; // real late sidestep scenario; not pre-staggered
    va.SampleContactPose(fa,fb);vb.SampleContactPose(fb,fa);a.CaptureSampledPose();b.CaptureSampledPose();var budget=new WorkBudget(100000);PairEvidence evidence;var observed=inspection.Inspect(a.Surface,b.Surface,a.MainTopology,b.MainTopology,ref budget,out evidence);if(frame==-1)startBad=observed!=PairInspection.ProvisionalOutsideBoth;if(observed==PairInspection.SurfaceContact)contacts++;if(observed==PairInspection.Indeterminate)unknown++;report.AppendLine(label+" frame="+frame+" observation="+observed+" faces="+evidence.SurfaceWitness.A+","+evidence.SurfaceWitness.B+" work="+budget.Spent);
    if(frame==-1||frame==Moves.All[moveIndex].Startup||observed==PairInspection.SurfaceContact&&contacts==1){using(var writer=new BinaryWriter(File.Create(Path.Combine(outputDirectory,label+"-"+frame+".contact.bin")))){a.WriteCapturedPose(writer);b.WriteCapturedPose(writer);}yield return new WaitForEndOfFrame();using(var writer=new BinaryWriter(File.Create(Path.Combine(outputDirectory,label+"-"+frame+".eof.bin")))){a.WriteLivePose(writer);b.WriteLivePose(writer);}}
    yield return null;
   }
   var animator=actorA.GetComponentInChildren<Animator>();var bridge=new AnimatorPhaseCollisionBridge(a,b,animator,Moves.All[moveIndex].Id);var localized=bridge.LocalizeSampledContact(0,.45,24,8);report.AppendLine(label+" sampledPhaseStart="+localized.Start+" foundContact="+localized.FoundContact+" lastSampledOutside="+localized.LastSampledOutside+" firstSampledContact="+localized.FirstSampledContact+" intervalUnqualified="+localized.IntervalUnqualified);var decision=bridge.Advance(.01,1.0/60,true);if(decision.EmitImpact||!decision.ConservativeStop)throw new InvalidOperationException("Missing temporal certificate became legal impact/clear");
   report.AppendLine(label+" sampledContacts="+contacts+" indeterminate="+unknown+" invalidReady="+startBad+" legalImpactUnproven=true");ReleaseActors();yield return null;
  }
 }
}
